(function(){
'use strict';
const $=id=>document.getElementById(id),byId=new Map(DECLIC_COURSES.map(d=>[d.id,d]));let selected=null,subject=null,returnToQuiz=false;
function idsFor(quiz){return [...new Set([...(quiz.documents||[]),...quiz.cards.flatMap(c=>(c.sources||[]).map(s=>s.documentId))])].filter(id=>byId.has(id));}
function available(quiz){return idsFor(quiz).length>0;}
function make(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e;}
function jump(page){const n=Number.isInteger(page)?Math.min(Math.max(page,1),selected.pageCount):1;$('course-page-select').value=String(n);const url=selected.url+'#page='+n;$('course-pdf').src=url;$('course-pdf-link').href=url;}
function setDocument(id,page=1){selected=byId.get(id);if(!selected)return;$('course-document').value=id;$('course-page-select').replaceChildren();for(let n=1;n<=selected.pageCount;n++){const o=make('option','',String(n));o.value=String(n);$('course-page-select').appendChild(o);}$('course-title').textContent=selected.title;$('course-page-count').textContent=selected.pageCount+' pages · copie du document';$('course-download').href=selected.url;$('course-download').textContent='Télécharger le PDF';jump(page);}
function open(quiz,source){const ids=idsFor(quiz);if(!ids.length)return;subject=quiz;returnToQuiz=!$('quiz-screen').classList.contains('hidden');$('library-screen').classList.add('hidden');$('quiz-screen').classList.add('hidden');$('course-screen').classList.remove('hidden');$('home-button').classList.remove('hidden');$('course-back').textContent=returnToQuiz?'← Revenir à la question':'← Mes quiz';$('course-document').replaceChildren();for(const id of ids){const d=byId.get(id),o=make('option','',d.title);o.value=id;$('course-document').appendChild(o);}const doc=source&&ids.includes(source.documentId)?source.documentId:ids[0];setDocument(doc,source?.page||1);$('course-subject').textContent=quiz.title;document.title='Déclic · Cours de '+quiz.title;$('course-subject').focus();window.scrollTo({top:0,behavior:'smooth'});}
function renderSources(host,sources,quiz){host.replaceChildren();const valid=(sources||[]).filter(s=>byId.has(s.documentId)&&Number.isInteger(s.page)&&s.page>0&&s.page<=byId.get(s.documentId).pageCount);host.classList.toggle('hidden',!valid.length);if(!valid.length)return;host.appendChild(make('h3','','La réponse dans ton document'));for(const source of valid){const d=byId.get(source.documentId),section=make('div','source-reference');section.appendChild(make('p','source-location',d.title+' · page '+source.page));const button=make('button','btn ghost','Voir la page du PDF');button.type='button';button.onclick=()=>open(quiz,source);section.appendChild(button);host.appendChild(section);}}
$('course-back').onclick=()=>{$('course-screen').classList.add('hidden');$('course-pdf').removeAttribute('src');if(returnToQuiz){$('quiz-screen').classList.remove('hidden');document.title='Déclic · '+subject.title;$('question').focus();}else DeclicLibrary.showLibrary();};$('course-document').addEventListener('change',()=>setDocument($('course-document').value));$('course-page-select').addEventListener('change',()=>jump(Number($('course-page-select').value)));
globalThis.DeclicCourses={available,open,renderSources};
})();
